CREATE VIEW gold.rpt_sap_monthly_executive AS WITH reporting_months AS (SELECT calmonth FROM gold.corr_sales_material_month UNION SELECT calmonth FROM gold.corr_stock_material_month UNION SELECT calmonth FROM gold.corr_service_material_month UNION SELECT calmonth FROM gold.corr_b2b_material_month),sales_monthly AS (SELECT calmonth, sum(bill_val) sales_bill_val, sum(bill_qty) sales_bill_qty, sum(do_qty) sales_do_qty, sum(do_amt) sales_do_amt, count(DISTINCT material) sales_materials FROM gold.corr_sales_material_month GROUP BY calmonth),sales_customer_monthly AS (SELECT calmonth, count(DISTINCT customer) sales_customers FROM gold.corr_sales_customer_month GROUP BY calmonth),stock_monthly AS (SELECT calmonth, sum(tot_stck) stock_qty, sum(val_stck) stock_val, count(DISTINCT material) stock_materials FROM gold.corr_stock_material_month GROUP BY calmonth),service_monthly AS (SELECT calmonth, sum(do_qty) svc_do_qty, sum(po_qty) svc_po_qty, CASE WHEN sum(po_qty) > 0 THEN sum(do_qty) / sum(po_qty) END svc_fill_rate, count(DISTINCT material) svc_materials FROM gold.corr_service_material_month GROUP BY calmonth),b2b_monthly AS (SELECT calmonth, sum(bill_val) b2b_bill_val, sum(bill_qty) b2b_bill_qty, count(DISTINCT material) b2b_materials FROM gold.corr_b2b_material_month GROUP BY calmonth),b2b_customer_monthly AS (SELECT calmonth, count(DISTINCT customer) b2b_customers FROM gold.corr_b2b_customer_month GROUP BY calmonth) SELECT m.calmonth, s.sales_bill_val, s.sales_bill_qty, s.sales_do_qty, s.sales_do_amt, s.sales_materials, sc.sales_customers, st.stock_qty, st.stock_val, st.stock_materials, sv.svc_do_qty, sv.svc_po_qty, sv.svc_fill_rate, sv.svc_materials, b.b2b_bill_val, b.b2b_bill_qty, b.b2b_materials, bc.b2b_customers, CASE WHEN s.sales_bill_val > 0 THEN s.sales_do_amt / s.sales_bill_val END do_amt_to_bill_val_ratio, CASE WHEN s.sales_bill_qty > 0 THEN st.stock_qty / s.sales_bill_qty END stock_to_sales_bill_qty_ratio FROM reporting_months m LEFT OUTER JOIN sales_monthly s ON m.calmonth = s.calmonth LEFT OUTER JOIN sales_customer_monthly sc ON m.calmonth = sc.calmonth LEFT OUTER JOIN stock_monthly st ON m.calmonth = st.calmonth LEFT OUTER JOIN service_monthly sv ON m.calmonth = sv.calmonth LEFT OUTER JOIN b2b_monthly b ON m.calmonth = b.calmonth LEFT OUTER JOIN b2b_customer_monthly bc ON m.calmonth = bc.calmonth
